/// <summary>
/// Check if same product is included by both the qualifying lines and the applying lines.
/// </summary>
/// <returns>True if some product is included by both the qualifying lines and the applying lines.</returns>
protected boolean hasProductInBothQualifyingAndApplyingLines()
{
    boolean ret = next hasProductInBothQualifyingAndApplyingLines();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        this.PeriodicDiscountType == RetailDiscountOfferTypeBase::Threshold)
    {
        Set qualifyingLineItemIdSet = new Set(Types::String);
        Set qualifyingLineProductVariantSet = new Set(Types::String);
        Set qualifyingLineProductVariantItemIdSet = new Set(Types::String);
        Set applyingLineItemIdSet = new Set(Types::String);
        Set applyingLineProductVariantSet = new Set(Types::String);
        Set applyingLineProductVariantItemIdSet = new Set(Types::String);
        boolean qualifyingLineHasGroupTypeAll = false;
        boolean applyingLineHasGroupTypeAll = false;

        RetailPeriodicDiscountLine qualifyingLine;
        RetailDiscountLineThresholdApplying applyingLine;

        while select qualifyingLine
            where qualifyingLine.OfferId == this.OfferId
                && qualifyingLine.LineType == RetailDiscountLineIncludeExcludeTypeBase::Include
                && qualifyingLine.IsDiscountApplyingLine == NoYes::No
        {
            GUPGroupAll groupCode = qualifyingLine.LinePricingGroupCode;
            if (groupCode == GUPGroupAll::All)
            {
                qualifyingLineHasGroupTypeAll = true;
                break;
            }
            else
            {
                this.constructProductSetFromPricingRule(
                    RetailPeriodicDiscount::findByOfferId(qualifyingLine.OfferId).HeaderPricingRule,
                    qualifyingLine.LinePricingRule,
                    qualifyingLineProductVariantSet,
                    qualifyingLineProductVariantItemIdSet,
                    qualifyingLineItemIdSet);
            }  
        }

        while select applyingLine
            where applyingLine.OfferId == this.OfferId
                && applyingLine.LineType == RetailDiscountLineIncludeExcludeTypeBase::Include
                && applyingLine.IsDiscountApplyingLine == NoYes::Yes
        {
            GUPGroupAll groupCode = applyingLine.LinePricingGroupCode;
            if (groupCode == GUPGroupAll::All)
            {
                applyingLineHasGroupTypeAll = true;
                break;
            }
            else
            {
                this.constructProductSetFromPricingRule(
                    RetailPeriodicDiscount::findByOfferId(applyingLine.OfferId).HeaderPricingRule,
                    applyingLine.LinePricingRule,
                    applyingLineProductVariantSet,
                    applyingLineProductVariantItemIdSet,
                    applyingLineItemIdSet);
            }
        }

        if ((qualifyingLineHasGroupTypeAll && applyingLineHasGroupTypeAll)                                                   ||
            (qualifyingLineHasGroupTypeAll && !(applyingLineItemIdSet.empty()   && applyingLineProductVariantSet.empty()))   ||
            (applyingLineHasGroupTypeAll   && !(qualifyingLineItemIdSet.empty() && qualifyingLineProductVariantSet.empty())) )
        {
            return true;
        }
        else
        {
            Set itemIdIntersectionSet = Set::intersection(applyingLineItemIdSet, qualifyingLineItemIdSet);
            Set qualifyingLineProductVariantItemIdIntersectionSet = Set::intersection(applyingLineItemIdSet, qualifyingLineProductVariantItemIdSet);
            Set applyingLineProductVariantItemIdIntersectionSet = Set::intersection(applyingLineProductVariantItemIdSet, qualifyingLineItemIdSet);

            Set productVariantIntersectionSet = Set::intersection(applyingLineProductVariantSet, qualifyingLineProductVariantSet);

            return !(itemIdIntersectionSet.empty()                              && 
                     qualifyingLineProductVariantItemIdIntersectionSet.empty()  &&
                     applyingLineProductVariantItemIdIntersectionSet.empty()    &&
                     productVariantIntersectionSet.empty()                      );
        }
    }

    return ret;
}

/// <summary>
/// Check if same product is included by multiple applying lines in some tier.
/// </summary>
/// <returns>True if some product is included by multiple lines.</returns>
protected boolean hasProductInMultipleApplyingLines()
{
    boolean ret = next hasProductInMultipleApplyingLines();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        this.PeriodicDiscountType == RetailDiscountOfferTypeBase::Threshold)
    {
        Set allApplyingLineItemIdSet = new Set(Types::String);
        Set currentApplyingLineItemIdSet = new Set(Types::String);
        Set allApplyingLineProductVariantSet = new Set(Types::String);
        Set currentApplyingLineProductVariantSet = new Set(Types::String);
        Set allApplyingLineProductVariantItemIdSet = new Set(Types::String);

        boolean applyingLineHasGroupTypeAll = false;

        RetailDiscountLineThresholdApplying applyingLine;

        while select applyingLine
            where applyingLine.OfferId == this.OfferId
                && applyingLine.LineType == RetailDiscountLineIncludeExcludeTypeBase::Include
                && applyingLine.IsDiscountApplyingLine == NoYes::Yes
        {
            if (applyingLineHasGroupTypeAll)
            {
                return true;
            }

            GUPGroupAll groupCode = applyingLine.LinePricingGroupCode;
            if (groupCode == GUPGroupAll::All)
            {
                applyingLineHasGroupTypeAll = true;
                continue;
            }
            else
            {
                this.constructProductSetFromPricingRule(
                    RetailPeriodicDiscount::findByOfferId(applyingLine.OfferId).HeaderPricingRule,
                    applyingLine.LinePricingRule,
                    currentApplyingLineProductVariantSet,
                    allApplyingLineProductVariantItemIdSet,
                    currentApplyingLineItemIdSet);

                Set itemIdIntersectionSet = Set::intersection(currentApplyingLineItemIdSet, allApplyingLineItemIdSet);
                Set productVariantIntersectionSet = Set::intersection(currentApplyingLineProductVariantSet, allApplyingLineProductVariantSet);

                if (itemIdIntersectionSet.empty() && productVariantIntersectionSet.empty())
                {
                    allApplyingLineItemIdSet = Set::union(currentApplyingLineItemIdSet, allApplyingLineItemIdSet);

                    itemIdIntersectionSet = Set::intersection(allApplyingLineItemIdSet, allApplyingLineProductVariantItemIdSet);
                    if (!itemIdIntersectionSet.empty())
                    {
                        return true;
                    }

                    currentApplyingLineItemIdSet = new Set(Types::String);

                    allApplyingLineProductVariantSet = Set::union(currentApplyingLineProductVariantSet, allApplyingLineProductVariantSet);
                    currentApplyingLineProductVariantSet = new Set(Types::String);
                }
                else
                {
                    return true;
                }
            }
        }

        return false;
    }

    return ret;
}

private void constructProductSetFromPricingRule(RecId _headerPricingRuleId, RecId _linePricingRuleId, Set _targetProductVariantSet, Set _targetProductVariantItemIdSet, Set _targetItemIdSet)
{
    GUPPricingRuleCopy pricingRuleCopy;
    GUPPricingRuleCopy pricingRuleCopyCustHeader;

    pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(_headerPricingRuleId));
    pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(_linePricingRuleId));

    boolean addProductVariants = pricingRuleCopy.ExclusionType == GUPPricingRuleExclusionType::ProductVariant;
    QueryRun queryRun;

    if (addProductVariants)
    {
        queryRun = new QueryRun(GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).addProductVariants().build());
    }
    else
    {
        queryRun = new QueryRun(GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).build());
    }

    while(queryRun.next())
    {
        if (addProductVariants)
        {
            this.addProductVariantNumberAndItemIdToTargetSet(queryRun, pricingRuleCopy.RuleId, _targetProductVariantSet, _targetProductVariantItemIdSet);
        }
        else
        {
            this.addItemIdToTargetSet(queryRun, pricingRuleCopy.RuleId, _targetItemIdSet);
        }
    }
}

private void addItemIdToTargetSet(QueryRun _queryRun, int64 _pricingRuleId, Set _targetSet)
{
    InventTable inventTable = _queryRun.get(tableNum(InventTable));
    GUPPricingRuleExclusionCopy excluded;

    select firstonly RecId from excluded where excluded.Exclusion == inventTable.ItemId && excluded.RuleId == _pricingRuleId;

    if (!excluded.RecId)
    {
        _targetSet.add(inventTable.ItemId);
    }
}

private void addProductVariantNumberAndItemIdToTargetSet(QueryRun _queryRun, int64 _pricingRuleId, Set _targetProductVariantSet, Set _targetItemIdSet)
{
    EcoResDistinctProductVariant productVariant = _queryRun.get(tableNum(EcoResDistinctProductVariant));
    GUPPricingRuleExclusionCopy excluded;

    select firstonly RecId from excluded where excluded.Exclusion == int642Str(productVariant.RecId) && excluded.RuleId == _pricingRuleId;

    if (!excluded.RecId)
    {
        _targetProductVariantSet.add(productVariant.DisplayProductNumber);

        str itemId = _queryRun.query().dataSourceTable(tableNum(InventTable)).rangeField(fieldnum(InventTable, ItemId)).value();
        _targetItemIdSet.add(itemId);
    }
}
